prompt:
Create unit `tasks` and implement `fill_from`: set every element at index >= start to v and leave the others unchanged, for start <= a.len(). The contract must state both parts.

Required signature (in unit `tasks`):
fn fill_from(a: &mut [i64], start: usize, v: i64) -> ()

reference.code:
spec fn start_ok(a: &[i64], start: usize) -> bool { start <= a.len() }

spec fn filled(a: &[i64], b: &[i64], start: usize, n: usize, v: i64) -> bool {
    a.len() == b.len() && (forall|k: usize| k < a.len() ==> ((k >= start && k < n ==> #[trigger] a[k] == v) && ((k < start || k >= n) ==> a[k] == b[k])))
}

spec fn filled_all(a: &[i64], b: &[i64], start: usize, v: i64) -> bool {
    a.len() == b.len() && (forall|k: usize| k < a.len() ==> ((k >= start ==> #[trigger] a[k] == v) && (k < start ==> a[k] == b[k])))
}

#[effects(pure)]
#[uses(start_ok, filled, filled_all)]
fn fill_from(a: &mut [i64], start: usize, v: i64) -> ()
    requires start_ok(a, start),
    ensures filled_all(a, old(a), start, v),
{
    let mut k: usize = start;
    while k < a.len()
        invariant start <= k, k <= a.len(), filled(a, old(a), start, k, v),
        decreases a.len() - k,
    {
        a[k] = v;
        k = k + 1;
    }
}
